-- DCH School catalog v3 additive registry and legacy alias layer.
-- This migration intentionally does not rewrite lesson_catalog IDs, lesson_content,
-- lesson_entitlements, learner state, published URLs, or existing access policies.

create table if not exists public.course_lesson_uid_registry (
  lesson_uid text primary key check (lesson_uid ~ '^les-[a-z0-9][a-z0-9_-]{0,80}$'),
  track_uid text not null,
  theme_uid text not null,
  module_uid text not null,
  display_code text not null check (display_code ~ '^[1-9][0-9]*\.[1-9][0-9]*\.[1-9][0-9]*$'),
  title_i18n jsonb not null default '{}'::jsonb,
  lifecycle_status text not null check (lifecycle_status in ('draft','review','published','unpublished','planned')),
  content_state text not null check (content_state in ('outline_only','content_draft','content_ready','localized','published')),
  is_published boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint course_lesson_uid_registry_publication_guard
    check (not is_published or (lifecycle_status = 'published' and content_state = 'published'))
);
create unique index if not exists course_lesson_uid_registry_track_code_idx
  on public.course_lesson_uid_registry(track_uid,display_code);

create table if not exists public.lesson_legacy_aliases (
  id bigint generated always as identity primary key,
  source_system text not null,
  alias_kind text not null,
  alias_value text not null,
  locale text,
  lesson_uid text not null references public.course_lesson_uid_registry(lesson_uid) on update restrict on delete restrict,
  mapping_state text not null check (mapping_state in ('editorial_approved','fragment_mapped','direct_candidate','needs_editorial_review','review')),
  access_behavior text not null default 'resolve_only' check (access_behavior = 'resolve_only'),
  created_at timestamptz not null default now()
);
create unique index if not exists lesson_legacy_aliases_identity_idx
  on public.lesson_legacy_aliases(source_system,alias_kind,alias_value,coalesce(locale,''),lesson_uid);
create index if not exists lesson_legacy_aliases_lookup_idx
  on public.lesson_legacy_aliases(source_system,alias_kind,alias_value,locale);

create table if not exists public.lesson_content_mapping_groups (
  mapping_id text primary key,
  source_legacy_id text not null,
  source_url text not null,
  source_fragment_topics text[] not null check (cardinality(source_fragment_topics) > 0),
  mapping_type text not null,
  confidence text not null,
  notes text not null default '',
  mapping_revision text not null
);
create table if not exists public.lesson_content_mapping_targets (
  mapping_id text not null references public.lesson_content_mapping_groups(mapping_id) on delete cascade,
  lesson_uid text not null references public.course_lesson_uid_registry(lesson_uid) on update restrict on delete restrict,
  target_code text not null,
  primary key(mapping_id,lesson_uid)
);

alter table public.course_lesson_uid_registry enable row level security;
alter table public.lesson_legacy_aliases enable row level security;
alter table public.lesson_content_mapping_groups enable row level security;
alter table public.lesson_content_mapping_targets enable row level security;
revoke all on public.course_lesson_uid_registry,public.lesson_legacy_aliases,
  public.lesson_content_mapping_groups,public.lesson_content_mapping_targets from anon,authenticated;
grant all on public.course_lesson_uid_registry,public.lesson_legacy_aliases,
  public.lesson_content_mapping_groups,public.lesson_content_mapping_targets to service_role;
grant usage,select on sequence public.lesson_legacy_aliases_id_seq to service_role;

on conflict (lesson_uid) do update set
 track_uid=excluded.track_uid,theme_uid=excluded.theme_uid,module_uid=excluded.module_uid,
 display_code=excluded.display_code,title_i18n=excluded.title_i18n,
 lifecycle_status=excluded.lifecycle_status,content_state=excluded.content_state,
 is_published=excluded.is_published,updated_at=now();

on conflict do nothing;

on conflict (mapping_id) do update set
 source_legacy_id=excluded.source_legacy_id,source_url=excluded.source_url,
 source_fragment_topics=excluded.source_fragment_topics,mapping_type=excluded.mapping_type,
 confidence=excluded.confidence,notes=excluded.notes,mapping_revision=excluded.mapping_revision;

on conflict (mapping_id,lesson_uid) do update set target_code=excluded.target_code;

create or replace function public.resolve_lesson_uid_aliases(
  p_source_system text,
  p_alias_kind text,
  p_alias_value text,
  p_locale text default null
)
returns table(lesson_uid text,display_code text,mapping_state text,is_published boolean)
language sql
stable
security definer
set search_path = ''
as $$
  select a.lesson_uid,r.display_code,a.mapping_state,r.is_published
  from public.lesson_legacy_aliases a
  join public.course_lesson_uid_registry r on r.lesson_uid=a.lesson_uid
  where a.source_system=p_source_system
    and a.alias_kind=p_alias_kind
    and a.alias_value=p_alias_value
    and (a.locale is null or a.locale=p_locale)
  order by r.display_code,a.lesson_uid;
$$;
revoke all on function public.resolve_lesson_uid_aliases(text,text,text,text) from public,anon,authenticated;
grant execute on function public.resolve_lesson_uid_aliases(text,text,text,text) to service_role;

comment on table public.course_lesson_uid_registry is
  'Staging registry for immutable v3 lesson UIDs. Display codes are presentation metadata, not identity.';
comment on table public.lesson_legacy_aliases is
  'Legacy IDs, Supabase slugs and localized URLs mapped to v3 UIDs. resolve_only never grants or inherits lesson access.';
comment on table public.lesson_content_mapping_groups is
  'Editorial source-fragment groups; one legacy source may map to many target lessons.';
comment on table public.lesson_content_mapping_targets is
  'Many-to-many target rows for editorial source-fragment groups.';
